enum mode { FIRST, NAME, SPACE, VALUE, VALUE_LF, SKIP, SKIP_LF,
            END_LF, DONE, BAD };

static __attribute__((always_inline)) inline void
consume(struct progress *s, struct bytes *b, u8 c)
{
    u32 n = s->n;
    switch (s->mode) {
    case FIRST:
        if ((!n && c != 'P') || n >= 31) {
            s->flags = UNSUPPORTED;
            break;
