                    "POST /mcp HTTP/1.1\r", 19))
            s->path = 1;
        else if (n == 19 && !__builtin_memcmp(b->data,
                    "POST /a2a HTTP/1.1\r", 19))
            s->path = 2;
        else if (n == 24 && !__builtin_memcmp(b->data,
                    "POST /delegate HTTP/1.1\r", 24))
