            if (s->seen) {
                s->flags = DUPLICATE;
                break;
            }
            s->seen = 1;
            s->mode = SPACE;
            return;
        }
        if (n >= 13 || (c | 32) != (u8)(n < 8 ?
                    0x2d666f6f72702d78ull >> ((n & 7) * 8) :
                    0x65636e6f6eull >> (((n - 8) & 7) * 8))) {
            s->mode = c == '\r' ? SKIP_LF : SKIP;
            if (c == '\n') s->flags = UNSUPPORTED;
